package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPolonnaruwaBank2 {
    private const val T = "පොළොන්නරු යුගයේ සිතුවම් හා මූර්ති කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පොළොන්නරු යුගයේ මූර්ති කලාවේ මුදුන්මල්කඩ ලෙස සැලකෙන ගල් විහාරය ඉදි කළ රජතුමා කවුද?", "පළමුවන මහා පරාක්‍රමබාහු රජතුමා", "පළමුවන විජයබාහු රජතුමා", "නිශ්ශංකමල්ල රජතුමා", "කීර්ති ශ්‍රී රාජසිංහ රජතුමා", "ක්‍රි.ව. 12 වන සියවසේ මහා පරාක්‍රමබාහු රජු විසින් උත්තරාරාමය හෙවත් ගල් විහාරය කරවන ලදී."),
        q("ගල් විහාරයේ එකම කළුගල් පර්වතයක නෙළා ඇති ප්‍රධාන බුදු පිළිම සංඛ්‍යාව කොපමණද?", "ප්‍රතිමා හතරක් (4)", "ප්‍රතිමා දෙකක් (2)", "ප්‍රතිමා දහයක් (10)", "එක් ප්‍රතිමාවක් (1) පමණක්", "විශාල හිඳි පිළිමය, විජ්ජාධර ගුහාවේ හිඳි පිළිමය, හිටි පිළිමය සහ සැතපෙන පිළිමය යන සතර මෙහි වේ."),
        q("ගල් විහාරයේ 'විශාල හිඳි බුදු පිළිමය' වැඩ සිටින ආසන ක්‍රමය හා හස්ත මුද්‍රාව කුමක්ද?", "වීරාසනය සහ ධ්‍යාන මුද්‍රාව", "පද්මාසනය සහ අභය මුද්‍රාව", "භද්‍රාසනය සහ විතර්ක මුද්‍රාව", "ලලිතාසනය සහ කටක මුද්‍රාව", "මීටර් 4.6ක් පමණ උස විශාල හිඳි පිළිමය වීරාසනයෙන් හා ධ්‍යාන මුද්‍රාවෙන් වැඩ සිටී."),
        q("ගල් විහාරයේ විශාල හිඳි පිළිමයට පිටුපසින් ගලේ කැටයම් කර ඇති විශේෂිත පසුබිම් නිර්මාණය කුමක්ද?", "මකර තොරණ, ප්‍රභා මණ්ඩලය සහ විමාන තුළ කුඩා බුදු රූප", "පෘතුගීසි කොඩි සහ නැව් රූප", "ගොවි කතුන්ගේ නැටුම් පෙළ", "සිංහල අක්ෂර සෙල්ලිපි පමණක්", "මකර තොරණ හා කුඩා ධ්‍යානි බුදු රූප සහිත පසුබිම් කැටයම පොළොන්නරු ශිල්පයේ සුවිශේෂීත්වයකි."),
        q("ගල් විහාරයේ 'හිටි පිළිමය' (උස මීටර් 7ක් පමණ) සම්බන්ධයෙන් පැවති ජනප්‍රිය මත දෙක මොනවාද?", "පරදුක්ඛදුක්ඛිත බුදු පිළිමය යන්න හා ආනන්ද හිමියන්ගේ ප්‍රතිමාව යන්න", "පරාක්‍රමබාහු රජුගේ හා විජයබාහු රජුගේ ප්‍රතිමා", "ශිව හා විෂ්ණු දේව ප්‍රතිමා", "මහා කාශ්‍යප හා සැරියුත් හිමි ප්‍රතිමා", "පපුව මත දෑත් බැඳගෙන සිටින මෙම පිළිමය පරදුක්ඛදුක්ඛිත බුදු රුවක් ලෙස අද විද්වතුන් පිළිගනී."),
        q("ගල් විහාර හිටි පිළිමයේ හිසට ඉහළින් කෙස් කැරලි හා උෂ්ණීෂය තිබීමෙන් තහවුරු වන සත්‍යය කුමක්ද?", "එය ආනන්ද හිමි රුවක් නොව ත්‍රිභංග බුදු පිළිමයක් බව", "එය හින්දු රජෙකුගේ රුවක් බව", "එය කැඩුණු දේව රුවක් බව", "එය ග්‍රීක දාර්ශනිකයෙකුගේ රුවක් බව", "උෂ්ණීෂය, දිගු කන් හා පද්ම පීඨය මෙය බුදු පිළිමයක් බවට ප්‍රබල පුරාවිද්‍යා සාක්ෂි සපයයි."),
        q("ගල් විහාරයේ 'හිටි පිළිමයේ' දෑත් පපුව හරහා බැඳගෙන සිටින ඉරියව්වෙන් ප්‍රකාශ වන සංකල්පය කුමක්ද?", "පරදුක්ඛදුක්ඛිත මහා කරුණාව", "වෙහෙසට නිදා ගැනීම", "සටනකට සූදානම් වීම", "ශීතලෙන් ආරක්ෂා වීම", "දෙවන සතියේ අනිමිසලෝචන පූජාව හෝ අන්‍යයන්ගේ දුක දෙස බලන කරුණාව මෙයින් දැක්වේ."),
        q("ගල් විහාරයේ 'සැතපෙන බුදු පිළිමයේ' (දිග මීටර් 14ක් පමණ) හිස හා පාද පිහිටා ඇති සියුම් කලා ලක්ෂණය කුමක්ද?", "ඉහළින් ඇති වම් පාදය මඳක් පසුපසට ඇදී තිබීම හා කොට්ටය හිසේ බරින් එබී තිබීම", "පාද දෙකම සමානව කෙළින් තබා කොට්ටය කෙළින් හතරැස්ව තැබීම", "හිස පොළොවට පහළින් එල්ලා වැටීම", "අත් දෙකම පිටුපසින් බැඳ තිබීම", "මෙම සියුම් නිරීක්ෂණයෙන් පිළිමය පිරිනිවන් මංචකයද සිංහසෙය්‍යාවද යන්න විචාරයට ලක් කෙරේ."),
        q("ගල් විහාර සැතපෙන පිළිමයේ කොට්ටය හිසේ බරට එබී ගොස් ඇති සේ කළුගලින් නෙළීමෙන් පෙනෙන්නේ කුමක්ද?", "දෘඪ ගලකින් මෘදු පුළුන් කොට්ටයක ගුණය මැවූ ශිල්පියාගේ අසමසම ප්‍රතිභාව", "ගල කැඩී කොට්ටය ගිලා බැසීම", "පසුකාලීනව සිමෙන්තියෙන් කොට්ටය සැදීම", "ශිල්පියාට මිණුම් වැරදී යාම", "රළු ග්නයිස් ගලට ජීවමාන මෘදු බවක් දීම ලොව විශිෂ්ටතම මූර්ති නිර්මාණ ලක්ෂණයකි."),
        q("ගල් විහාර සැතපෙන බුදු පිළිමයේ දකුණු අත්ල හා දෙපතුල්වල කැටයම් කර ඇති සංකේතය කුමක්ද?", "පිපුණු නෙළුම් මල් සංකේත (පද්ම ලකුණු)", "යුද කඩු සංකේත", "චීන මකර සංකේත", "සිංහල අංක සංකේත", "මහාපුරුෂ ලක්ෂණ අනුව සැතපෙන පිළිමයේ පතුලේ සහ අත්ලේ මංගල පද්ම සටහන් නෙළා ඇත."),
        q("ගල් විහාරයේ 'විජ්ජාධර ගුහාව' ඇතුළත නෙළා ඇති කුඩා හිඳි බුදු පිළිමය ඉහළින් කැටයම් කර ඇති විශේෂත්වය කුමක්ද?", "මකර තොරණ, පිළිමයට සෙවණ දෙන ඡත්‍රය සහ පරිවාර බෝසත්-දේව රූප", "කැටයම් රහිත සම්පූර්ණ හිස් බිත්තියක්", "වීදුරු ජනෙල් රාමු පෙළක්", "මහනුවර පෙරහැරේ ඇතුන් රූප", "පර්වතය ඇතුළට කුඩා ලෙන් ගුහාවක් ලෙස හාරා ඡත්‍රය හා චාමරධාරී දේව රූප නෙළා ඇත."),
        q("පොළොන්නරුවේ පොත්ගුල් වෙහෙර අසල පිහිටි සුප්‍රකට 'පරාක්‍රමබාහු ප්‍රතිමාව' කුමන ස්වභාවයකින් යුක්තද?", "පුස්කොළ පොතක් හෝ නූල් වියදණ්ඩක් දෑතින් අල්ලාගෙන සිටින ගාම්භීර හිටි ප්‍රතිමාව", "සිංහාසනයක හිඳගෙන සිටින යුද සෙන්පති ප්‍රතිමාව", "අශ්වයෙකු පිට නැගුණු ප්‍රතිමාව", "ලෝකඩවලින් තැනූ සැතපෙන ප්‍රතිමාව", "මීටර් 3.5ක් උසැති මෙම පිළිමයේ රැවුල, ජටාව හා දෑත්වල ඇති පුස්කොළ පොත සුවිශේෂීය."),
        q("පොත්ගුල් වෙහෙර ප්‍රතිමාව සම්බන්ධයෙන් විද්වතුන් අතර පවතින ප්‍රධාන මත දෙක මොනවාද?", "පරාක්‍රමබාහු රජු හෝ සෘෂිවරයෙක්", "කාශ්‍යප රජු හා දුටුගැමුණු රජු", "මහින්ද හිමි හා අනුලා දේවිය", "විජය රජු හා කුවේණිය", "මෙම රුව රජතුමා 'රාජ්‍ය ධර්මය හෙවත් යුග ධුරය' දරන ආකාරය හෝ සෘෂි රුවක් බවට මත දෙකකි."),
        q("පොළොන්නරු යුගයේ 'පරාක්‍රමබාහු' (සෘෂි) ප්‍රතිමාවේ පෙනෙන මූර්ති ශිල්පියාගේ විශිෂ්ට මානව රූප කුසලතාව කුමක්ද?", "මහලු වියේ ගාම්භීර බව, විවෘත උදරය හා ස්වාභාවික මුහුණු ප්‍රකාශනය", "තරුණ කාන්තාවකගේ ලාලිත්‍යමය හැඩය", "සම්පූර්ණ වියුක්ත ජ්‍යාමිතික රටාව", "රාක්ෂ හා බියකරු ස්වරූපය", "පිළිමයේ කැපී පෙනෙන යථාර්ථවාදී ලක්ෂණ හා පුද්ගල පෞරුෂය ශ්‍රී ලංකාවේ විරල මූර්ති ගුණයකි."),
        q("පොළොන්නරු යුගයේදී 'සඳකඩපහණෙහි' සිදු වූ ප්‍රධාන ආගමික හා සංස්කෘතික වෙනස්කම කුමක්ද?", "සත්ව පෙළෙන් 'ගවයා' (වෘෂභයා) ඉවත් කිරීම", "සියලුම සතුන් ඉවත් කර මසුන් පමණක් යෙදීම", "සඳකඩපහණ හතරැස් පෙට්ටියක් බවට පත් කිරීම", "අලි රූප පමණක් සියයක් යෙදීම", "හින්දු චෝල ආභාසය හා බලපෑම නිසා ගවයා පූජනීය සතෙකු ලෙස සලකා පෑගීම වැළැක්වීමට ගවයා ඉවත් කෙරිණි."),
        q("පොළොන්නරුවේ වටදාගෙය අබියස ඇති සඳකඩපහණෙහි සතුන් තිදෙනා කැටයම් කර ඇති ආකාරය අනුරාධපුරයෙන් වෙනස් වන්නේ කෙසේද?", "ඇතා, අශ්වයා සහ සිංහයා වෙන වෙනම තීරු තුනක කැටයම් කර තිබීම", "සතුන් තිදෙනාම එකම තීරුවේ පේළියට තැබීම", "සිංහයා ඉවත් කර ගවයා පමණක් තැබීම", "සඳකඩපහණ මැදින් නෙළුම් මල ඉවත් කිරීම", "පොළොන්නරු වටදාගේ සඳකඩපහණේ ඇත්, අස්, සිංහ යන සතුන් වෙන වෙනම වළලු තුනක දක්වා ඇත."),
        q("පොළොන්නරුවේ 'ශිව දේවාලවලින්' හමු වූ ලෝකඩ ප්‍රතිමා (උදා: ශිව නටරාජ) අයත් වන්නේ කුමන ඉන්දීය කලා සම්ප්‍රදායටද?", "දකුණු ඉන්දීය චෝල ලෝකඩ මූර්ති සම්ප්‍රදාය", "උතුරු ඉන්දීය මූගල් සම්ප්‍රදාය", "බෞද්ධ ගන්ධාර සම්ප්‍රදාය", "සාංචි හා අමරාවතී සම්ප්‍රදාය", "පොළොන්නරුවේ චෝල පාලන සමයේ හා පසුකාලීන හින්දු දේවාලවල විශිෂ්ට චෝල ලෝකඩ ප්‍රතිමා හමු වී ඇත."),
        q("පොළොන්නරුවෙන් හමු වූ 'ශිව නටරාජ' ලෝකඩ ප්‍රතිමාවේ කලාත්මක විශේෂත්වය කුමක්ද?", "ගිනි වළල්ලක් මැද අපස්මාර යක්ෂයා පාගාගෙන තාණ්ඩව නර්තනයේ යෙදීම", "පද්මාසනයෙන් වැඩ සිට භාවනා කිරීම", "අශ්වයෙකු පිට යුද්ධයට යාම", "නෙළුම් මලක් අතින් ගෙන නිදා සිටීම", "මැවීම, පැවැත්ම හා විනාශය යන විශ්ව චක්‍රය සංකේතවත් කරන නටරාජ රුව විශිෂ්ට කලා කෘතියකි."),
        q("පොළොන්නරු ශිව දේවාල අංක 5 ආශ්‍රිතව හමු වූ තවත් ලෝක ප්‍රකට චෝල ආභාසිත ලෝකඩ ප්‍රතිමා මොනවාද?", "පාර්වතී, සුන්දරමූර්ති නායනාර්, ගණේෂ හා කරෛක්කාල් අම්මයාර් ප්‍රතිමා", "තාරා දේවි හා වෙහෙරගල බෝසත් ප්‍රතිමා", "මහසෙන් රජුගේ ලෝකඩ ප්‍රතිමාව", "විලෙන්ඩෝෆ් වීනස් ප්‍රතිමාව", "කොළඹ කෞතුකාගාරයේ ඇති මෙම ලෝකඩ හින්දු ප්‍රතිමා ලොව උසස්ම ලෝකඩ මූර්ති අතර වේ."),
        q("පොළොන්නරුවේ 'නිශ්ශංකලතා මණ්ඩපය' පුරාණ ශිලා කැටයම් අතර අද්විතීය වන්නේ කුමන කුළුණු හැඩය නිසාද?", "වක්‍ර නෙළුම් දඬු හා පොහොට්ටු කුළුණු", "සෘජු කළුගල් චතුරස්‍ර කුළුණු", "ලීයෙන් තැනූ ඇම්බැක්කේ කුළුණු", "ග්‍රීක කොරින්තියානු කුළුණු", "නිශ්ශංකමල්ල රජු ධර්ම ශ්‍රවණය කළ මෙම මණ්ඩපයේ වක්‍ර ශිලා කුළුණු දැඩි ගලට සියුම් නම්‍යතාවක් දෙයි."),
        q("පොළොන්නරුවේ 'වටදාගෙය' ආශ්‍රිතව ඇති කැටයම් අතර ප්‍රධාන වශයෙන් දක්නට ලැබෙන ශිලා අංගය කුමක්ද?", "සඳකඩපහණ, නාගරාජ මුරගල්, කොරවක්ගල්, මල් රටා ගල් වැට හා සතර බුදු පිළිම", "මහනුවර පෙරහැරේ දැව කැටයම්", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ", "රන් ආලේපිත තෙල් සායම් පුවරු", "වෘත්තාකාර වේදිකා දෙකක් මත ගොඩනැගූ පොළොන්නරු වටදාගෙය මූර්ති හා වාස්තු කලා සංකලනයකි."),
        q("පොළොන්නරුවේ 'හැටදාගෙය' සහ 'අටදාගෙය' වැනි දළදා මැදුරුවල බිත්ති අලංකරණයේදී භාවිත කළ ප්‍රධාන කැටයම් මොනවාද?", "සිංහ, නැටුම් හා පලාපෙති කැටයම්", "කාර්මික යකඩ තහඩු", "චීන මැටි පිඟන් කැබලි", "ප්ලාස්ටික් සැරසිලි", "පියගැටපෙළ දෙපස මුරගල් හා බිත්ති පාදමේ සිංහ හා වාමන රූප දක්නට ලැබේ."),
        q("පොළොන්නරුවේ 'රාජ සභා මණ්ඩපය' (පරාක්‍රමබාහු සහ නිශ්ශංකමල්ල) පාදමෙහි නෙළා ඇති දිගු සත්ව රූප තීරුව කුමක්ද?", "ඇතුන්, සිංහයන් සහ වාමන රූප පෙළ", "මසුන් හා කිඹුලන් පෙළ", "මුවන් හා හාවුන් පෙළ", "අශ්වයන් හා ඔටුවන් පෙළ", "විශාල ශිලා වේදිකාව දරා සිටින අයුරින් ඇත් හා සිංහ රූප පෙළට කැටයම් කර තිබේ."),
        q("පොළොන්නරුවේ 'නිශ්ශංකමල්ල රාජ සභාවේ' පිටුපසින් තිබූ සුප්‍රකට සිංහ පීඨය කවරක්ද?", "රජුගේ ශිලා සිංහාසන ප්‍රතිමාව", "වතුර පොකුණක ජල පීල්ල", "දාගැබක කොත් කැරැල්ල", "විහාරයක මුරගලක්", "කොළඹ කෞතුකාගාරයේ දැනට ඇති මෙම විශාල සිංහ මූර්තිය මත රජුගේ සිංහාසනය පිහිටුවා තිබිණි."),
        q("පොළොන්නරු යුගයේ 'ශිව දේවාල අංක 2' (වානවන්මාදේවි ඊශ්වරමුඩයාර්) සම්පූර්ණයෙන්ම ඉදිකර ඇත්තේ කුමන ද්‍රව්‍යයකින්ද?", "බදාම නොමැතිව සකස් කළ කළුගල් කුට්ටිවලින් (Dry masonry)", "රතු ගඩොල් හා මැටිවලින් පමණක්", "කොස් ලී හා පිදුරුවලින්", "සිමෙන්ති හා යකඩ කම්බිවලින්", "චෝල ද්‍රවිඩ ගෘහ නිර්මාණ ශෛලියෙන් කළුගල් එකට බැඳ මෙම පැරණිතම ගොඩනැගිල්ල නිමවා ඇත."),
        q("පොළොන්නරු යුගයේ 'ගඩොල් හා බදාම' මූර්ති කලාවේදී (Stucco) පොළොන්නරුවේ 'ලංකාතිලක' හා 'ථූපාරාම' පිටත බිත්තිවල නිමවා ඇත්තේ මොනවාද?", "දේව රූප, ඇත් හිස් හා සිංහ රූප", "නූතන ගොඩනැගිලි සිතියම්", "රෝම සෙනෙට් සභිකයන්", "ප්‍රාග් ඓතිහාසික දඩයම් දර්ශන", "පොළොන්නරු ගඩොල් විහාරවල පිටත බිත්ති පුරා අලංකාර විමාන මූර්ති දැකිය හැක."),
        q("පොළොන්නරු යුගයේ 'වටදාගේ' වල ඇති චූල හිඳි බුදු පිළිම සතරේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "සිනිඳු පාරදෘශ්‍ය චීවරය හා පොළොන්නරු ආරේ පිරුණු මුහුණ", "ගිනිසිළු මහනුවර රැලි චීවරය", "ත්‍රිභංග හිටි ඉරියව්ව", "ලෝකඩ වාත්තු ක්‍රමය", "සතර දිසාවේ තැබූ මෙම හුණුගල්/කළුගල් පිළිම සමාධි භාවය හා සරල සුමට බව පෙන්වයි."),
        q("ගල් විහාරයේ 'හිටි පිළිමයේ' සහ 'විශාල හිඳි පිළිමයේ' මුහුණු සමාධි පිළිමයට වඩා වෙනස් වන්නේ කෙසේද?", "වඩා පළල් වූ මුහුණ, ඝන දෙතොල් හා තියුණු බැම රේඛා පැවතීම", "මුහුණු ඉතා කුඩා ත්‍රිකෝණ වීම", "රැවුල සහ උඩු රැවුල නෙළා තිබීම", "ඇස් සම්පූර්ණයෙන් වසා නොමැතිව විශාල රවුම් වීම", "පොළොන්නරු යුගයේදී දකුණු ඉන්දීය බලපෑමත් සමඟ බුදු රුවේ මුහුණු ලක්ෂණ මඳක් වෙනස් විය."),
        q("පොළොන්නරු යුගයේ 'මුරගල්' කලාව අනුරාධපුර රත්නප්‍රාසාද මුරගල හා සසඳන විට පෙනෙන වෙනස කුමක්ද?", "අලංකරණ විස්තර වැඩි වුවද අනුරාධපුරයේ තිබූ සියුම් ලාලිත්‍යය තරමක් දැඩි වීම", "මුරගල් සම්පූර්ණයෙන් හිස් ගල් පුවරු බවට පත්වීම", "නාගරාජයා වෙනුවට අශ්වයෙකු නෙළීම", "මුරගල් ලීයෙන් පමණක් තැනීම", "පොළොන්නරුවේ වටදාගේ මුරගල් ඉතා සුන්දර වුවද රූපය තරමක් ඝන හා ජවසම්පන්න ස්වරූපයක් ගනී."),
        q("පොළොන්නරුවේ 'රන්කොත් වෙහෙර' සහ 'කිරි වෙහෙර' අසල ඇති විශාල බදාම පිළිම හා කැටයම් මගින් පෙනෙන්නේ කුමක්ද?", "විශාල ආගමික නිර්මාණ ප්‍රිය කිරීම", "කුඩා පිළිම පමණක් තැනීම", "ගඩොල් තාක්ෂණය අමතක කිරීම", "ස්තූප කිසිවක් නොතැනීම", "විශාල ගඩොල් ස්තූප හා වාහල්කඩ බදාම කැටයම් පොළොන්නරු රාජකීය ශ්‍රී විභූතිය දක්වයි."),
        q("පොළොන්නරුවේ 'සත්මහල් ප්‍රාසාදය' වැනි අසාමාන්‍ය ගෘහ නිර්මාණයේ පිටත මහල්වල නෙළා තිබුණේ කුමන මූර්තිද?", "සෑම මහලකම දෙපස ආරුක්කු තුළ බදාම දේව රූප", "ග්‍රීක යුද අශ්ව රථ", "වීදුරු කැටයම් ජනෙල්", "චීන අකුරු පුවරු", "තායිලන්ත හා කාම්බෝජ ආභාසය ගත් පිරමීඩාකාර ස්තූප ප්‍රාසාදයේ සිව් දිශාවේ බදාම රූප වේ."),
        q("පොළොන්නරු යුගයේ 'ලෝකඩ මූර්ති කලාවේ' දක්නට ලැබෙන 'කුහර වාත්තු' (Hollow cast) සහ 'ඝන වාත්තු' අතරින් ශිව නටරාජ ප්‍රතිමාව අයත් වන්නේ කුමකටද?", "ඝන ලෝකඩ ඉටි මැකුම් වාත්තුවට (Solid lost-wax cast)", "මැටි පිළිස්සුම් ක්‍රමයට", "තහඩු නැවීමේ ක්‍රමයට", "වැලි අච්චු ක්‍රමයට පමණක්", "අධික බරකින් යුත් සම්පූර්ණ ඝන ලෝකඩ ප්‍රතිමා ලෙස මෙම හින්දු ප්‍රතිමා නිර්මාණය කර තිබේ."),
        q("පොළොන්නරුවේ 'ගල් විහාර හිටි පිළිමයේ' චීවර රැලි නෙළා ඇති ආකාරය කුමන ලක්ෂණයකින් යුක්තද?", "මඳක් තියුණු සහ සමාන්තර ද්විත්ව රේඛා රැලි (Double-line folds) ලෙස", "සම්පූර්ණ රැලි රහිත සිනිඳු පෘෂ්ඨයක් ලෙස", "අක්‍රමවත් කොටු රටාවක් ලෙස", "පිටුපසින් පමණක් රැලි ඇඳීම", "ද්විත්ව රේඛා ශෛලියෙන් රැලි නෙළීම පොළොන්නරු ගල් විහාර ප්‍රතිමාවල කැපී පෙනෙන ලක්ෂණයකි."),
        q("ගල් විහාරයේ 'විශාල හිඳි පිළිමයේ' හිසට ඉහළින් කැටයම් කර ඇති කුඩා බුදු රූප කිහිපයෙන් සංකේතවත් කරන්නේ කුමක්ද?", "සතර බුදුවරු හෝ දස දිශාවේ බුදුවරුන්ගේ ගෞරවය", "රජතුමාගේ පවුලේ සාමාජිකයන්", "ගල් විහාර ශිල්පීන්ගේ රූප", "සත්ව රාශි චක්‍රය", "මහායාන හා පොළොන්නරු මිශ්‍ර ආභාසය අනුව විමාන හතරක් තුළ කුඩා බුදු රූප තබා ඇත."),
        q("පොළොන්නරු යුගයේ 'වටදාගේ' වටා ඇති ගල් වැටෙහි (Railings) කැටයම් කර ඇති මෝස්තරය කුමක්ද?", "සිව්පෙති නෙළුම් මල් මෝස්තර", "සර්පිලාකාර නාග රූප", "මකර හිස් පෙළ", "කුරුලු පිහාටු රටා", "සෑම හතරැස් පුවරුවකම සමමිතික සිව් පෙති මල් මෝස්තරයක් අලංකාරව කැටයම් කර ඇත."),
        q("පොළොන්නරුවේ 'පරාක්‍රමබාහු ප්‍රතිමාවේ' හිසේ පැළඳ සිටින 'ජටා මකුටය' පිළිබඳව නිවැරදි නිරීක්ෂණය කුමක්ද?", "සිවුරු නැතිව රාජකීය හෝ සෘෂි හිස් ජටාවක් සේ උස්ව බැඳ තිබීම", "එය බුදු පිළිමයක සිරස්පත හා සමාන වීම", "එය පෘතුගීසි යුද හිස්වැස්මක් වීම", "හිස සම්පූර්ණයෙන්ම මුඩු කර තිබීම", "රජුන්ගේ හා තාපසවරුන්ගේ හිසකෙස් බැඳීමේ ක්‍රමය අනුව උස් ජටාවක් ලෙස නෙළා තිබේ."),
        q("පොළොන්නරු යුගයේ 'කැටයම් කලාවේ' දක්නට ලැබෙන 'වාමන රූප' අනුරාධපුර වාමන රූපවලට වඩා කෙබඳුද?", "වඩාත් ක්‍රියාශීලීව හා තදින් බර උසුලන හෝ නටන ලෙස කැටයම් කර තිබීම", "නිදාගෙන සිටින සේ නෙළා තිබීම", "කිසිදු චලනයක් නැතිව තැබීම", "ලෝහවලින් පමණක් වාත්තු කිරීම", "රාජ සභාව හා වටදාගෙය වැනි ස්ථානවල වාමන රූප ජවසම්පන්නව කැටයම් කර ඇත."),
        q("පොළොන්නරු යුගයේ 'මකර තොරණ' මූර්ති කලාවේ (උදා: ගල් විහාරය, තිවංක) දක්නට ලැබෙන ප්‍රධාන ලක්ෂණය කුමක්ද?", "දෙපසින් මකරුන් දෙදෙනෙකු හා මුදුනින් කීර්තිමුඛ රුවක් පැවතීම", "මකරා වෙනුවට අශ්වයෙකු පමණක් තැබීම", "සම්පූර්ණ වීදුරු ආරුක්කුවක් තැබීම", "සරල ලී කෝටු රාමුවක් තැබීම", "දෙපස මකර මුඛ හා ඉහළ මැද කීර්තිමුඛය යෙදීම පොළොන්නරු-මහනුවර තොරණ් සම්ප්‍රදායයි."),
        q("පොළොන්නරු යුගයේ 'කුමාර පොකුණ' ආසන්නයේ ඇති කැටයම් මගින් පෙනෙන්නේ කුමන උද්‍යාන කලා අංගයද?", "කිඹුල් හා මකර මුඛ ජල පීලි සහිත රාජකීය ස්නාන පොකුණු අලංකරණය", "නූතන නාන කාමර පිඟන් ගඩොල්", "ග්‍රීක කුළුණු සෙල්ලම් පිටිය", "මැටි පිළිස්සීමේ කම්හල", "නන්දන උයනේ තිබූ කුමාර පොකුණේද ජල ගැලීම් අලංකරණයට ගල් කැටයම් යොදා ඇත."),
        q("පොළොන්නරුවේ 'ශිව දේවාලවල' කැටයම් කර ඇති ගල් බිත්ති අලංකරණ අතර ප්‍රමුඛ වන්නේ මොනවාද?", "කුඩු ආරුක්කු හා දේව කුටි", "බෞද්ධ සඳකඩපහණ හා සිරිපතුල්", "නූතන සිංහල කවි සෙල්ලිපි", "වීදුරු කැඩපත් පුවරු", "දකුණු ඉන්දීය චෝල හින්දු ගෘහ නිර්මාණ ලක්ෂණ ශිව දේවාල ගල් බිත්තිවල මැනවින් දිස්වේ."),
        q("පොළොන්නරුවේ 'මහා පරාක්‍රමබාහු' රජුගේ කලා සේවය හේතුවෙන් කලා ක්ෂේත්‍රයේ ඇති වූ ප්‍රධාන පිබිදීම කුමක්ද?", "සුවිසල් ආගමික හා රාජකීය වාස්තු-මූර්ති-චිත්‍ර කලා පුනරුදයක් බිහිවීම", "කලාව සම්පූර්ණයෙන් විනාශ වී යාම", "චීන සෙරමික් කලාව පමණක් පැවතීම", "ලෝකඩ භාවිතය තහනම් කිරීම", "තිවංක, ගල් විහාර, ලංකාතිලක හා පරාක්‍රම සමුද්‍රය ආශ්‍රිත කලා නිර්මාණ මෙම රාජ්‍ය සමයේ බිහිවිය."),
        q("පොළොන්නරු යුගයේ 'වටදාගේ' වල ඇති චූල හිඳි බුදු පිළිම සතරට අනුරූපව 'හිටි පිළිම' සතරක් ඇති ගොඩනැගිල්ල කුමක්ද?", "හැටදාගෙය හෝ අටදාගෙය උඩු මහල", "සත්මහල් ප්‍රාසාදය පමණක්", "නිශ්ශංකලතා මණ්ඩපය", "කුමාර පොකුණ", "දළදා මන්දිර ආශ්‍රිතවද ධාතු මන්දිරයේ බුදු පිළිම තැන්පත් කර පූජා පවත්වා ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාරය' තනි පිහිටි කළුගල් පර්වතයක් තුළ කෙටීමේදී ශිල්පියා මුහුණ දුන් ප්‍රධාන අභියෝගය කුමක්ද?", "එකම පර්වතයේ ඉරිතැළීම් හා ඝනත්ව වෙනස්කම් ජය ගනිමින් මීටර් ගණනක් ගැඹුරට කැටයම් කිරීම", "ගල ඉතා මෘදු මැටි වීම නිසා දිය වී යාම", "ලෝහ උණු කිරීමට දර නොමැති වීම", "කුඩා කඩදාසියක සැලැස්ම ඇඳීමට නොහැකි වීම", "තද බහුතර ග්නයිස් ගල කැඩී නොයන සේ අතිවිශාල පිළිම 4ක් එක පෙළට නෙළීම විශ්මයජනකය."),
        q("පොළොන්නරු යුගයේ 'තිවංක' හා 'ගල් විහාර' පිළිම අතර භාවිත කර ඇති ප්‍රධාන මූර්ති මාධ්‍ය වෙනස කුමක්ද?", "තිවංක පිළිමය ගඩොල්-බදාම වන අතර ගල් විහාර පිළිම කළුගල් පර්වත වීම", "තිවංක පිළිමය ලෝකඩ වන අතර ගල් විහාරය ලී වීම", "දෙකම පිළිස්සූ මැටි පිළිම වීම", "ගල් විහාරය ගඩොල් වන අතර තිවංකය කළුගල් වීම", "ගඩොල් හුණු බදාම මූර්ති හා කළුගල් මූර්ති යන දෙවර්ගයම පොළොන්නරුවේ උච්චතම තලයේ පැවතිණි."),
        q("පොළොන්නරුවේ 'නෙළුම් පොකුණ' (Lotus Pond) කලා නිර්මාණයක් ලෙස අගය කරන්නේ කුමන හැඩතලය නිසාද?", "පිපුණු පෙති අටේ නෙළුම් මලක් ආකාරයෙන් පහළට කුඩා වන ශිලා පඩිපෙළ", "චතුරස්‍ර කොන්ක්‍රීට් පිහිනුම් තටාකයක් වීම", "සිංහයෙකුගේ හැඩයෙන් තැනීම", "වීදුරු බිත්තිවලින් තැනීම", "ජ්‍යාමිතික නෙළුම් පෙති අටේ සමමිතිය හා ස්නාන පොකුණු තාක්ෂණය එහි මනාව එක්ව ඇත."),
        q("පොළොන්නරු යුගයේ 'මූර්ති කලාවේ' දක්නට ලැබෙන ලෝකඩ ප්‍රතිමා කලාව හඳුනා ගැනීමේදී ඒවා අයත් ප්‍රධාන ආගම් දෙක මොනවාද?", "බුද්ධාගම සහ හින්දු ආගම (ශෛව භක්තිය)", "ක්‍රිස්තියානි සහ ඉස්ලාම් ආගම", "ප්‍රාග් ඓතිහාසික හා ග්‍රීක දේව ආගම", "තාඕ සහ කොන්ෆියුසියස් දහම", "බෞද්ධ බුදු-බෝසත් රූප මෙන්ම ශිව-පාර්වතී හින්දු ලෝකඩ ප්‍රතිමාද පොළොන්නරුවෙන් බහුලව හමුවේ."),
        q("පොළොන්නරුවේ 'ශිව නටරාජ' ප්‍රතිමාවේ පාදයට යටින් පාගාගෙන සිටින කුරු මිනිස් රුව කවුරුන්ද?", "අපස්මාර (මුයලකන්) යක්ෂයා", "විෂ්ණු දෙවියන්", "පරාක්‍රමබාහුගේ සේවකයෙක්", "නටන ශිෂ්‍යයෙක්", "මිනිසාගේ අවිද්‍යාව මර්දනය කර ඥානය ලබා දීම මෙම සංකේතාර්ථයෙන් ප්‍රකාශ වේ."),
        q("පොළොන්නරුවේ 'නිශ්ශංකමල්ල' රජු විසින් කරවන ලද 'ගල්පොත' ශිලා ලේඛනය අසල ඇති කලාත්මක කැටයම කුමක්ද?", "ගජලක්ෂ්මී හා හංස පෙළ කැටයම්", "වෙස්සන්තර ජාතක කතා පෙළ", "සීගිරි ලලනාවන් දෙදෙනා", "මහනුවර ඇසළ පෙරහැර", "පොතක හැඩය ගත් ගල්පොත දෙපස අලංකාර හංස පෙළ හා ගජලක්ෂ්මී කැටයම් දක්නට ඇත."),
        q("පොළොන්නරු යුගයේ 'ලෝකඩ බුදු පිළිම' අතර කුඩා ප්‍රමාණයේ අතේ ගෙන යා හැකි පිළිම නිපදවූයේ කුමක් සඳහාද?", "පෞද්ගලික වන්දනාව, ආරක්ෂාව හා සංචාරක භික්ෂූන්ගේ භාවිතයට", "ළමුන්ගේ සෙල්ලම් බඩු ලෙස", "වෙළඳ බර කිරන පඩි ලෙස", "මසුන් ඇල්ලීමේ ඇම ලෙස", "දෛනික වන්දනාව හා ආශිර්වාදය සඳහා කුඩා ලෝකඩ හා රන් පිළිම රාශියක් නිපදවා ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාර සැතපෙන පිළිමය' නෙළා ඇති ඉරියව්වේදී හිස හා අත පිහිටා ඇති ආකාරය කුමක්ද?", "දකුණු ඇලයෙන් සැතපී දකුණු අත හිසට තබා වම් අත කලවා මත දිග හැර තිබීම", "උඩුබැලි අතට වැතිර දෙඅත් බැඳ සිටීම", "මුහුණ යටට හරවා නිදා සිටීම", "දණහිස් නවා වාඩි වී සිටීම", "සම්භාව්‍ය බෞද්ධ සිංහසෙය්‍යා සැතපෙන ඉරියව්ව ගල් විහාර පිළිමයේ ඉතා සංයමයෙන් දැක්වේ."),
        q("පොළොන්නරු යුගයේ 'දොරටුපාල රූප' (Dvarapala) හා මුරගල් අතර පවතින සමානකම කුමක්ද?", "දෙවර්ගයම විහාර ආරක්ෂකයින් ලෙස පිවිසුමේ දෙපස නෙළා තිබීම", "දෙවර්ගයම සත්ව රූප පමණක් වීම", "දෙවර්ගයම වහලය මත තැබීම", "දෙවර්ගයම කළු තීන්තෙන් ඇඳීම", "වටදාගේ, හැටදාගේ ආදී ස්ථානවල පිවිසුම් අභියස ආරක්ෂාව හා ගෞරවය සංකේතවත් කිරීමට යෙදිණි."),
        q("පොළොන්නරුවේ 'වටදාගෙය' තුළ වැඩ සිටින බුදු පිළිම හතරේ හස්ත මුද්‍රාව කුමක්ද?", "ධ්‍යාන මුද්‍රාව හා වීරාසනය", "භූමිස්පර්ශ මුද්‍රාව", "ධර්මචක්‍ර මුද්‍රාව", "වරද මුද්‍රාව", "පූජනීය ශාන්තිය පිළිබිඹු කරමින් සිව් දිසාවේම හිඳි බුදු පිළිම ධ්‍යාන මුද්‍රාවෙන් පිහිටුවා ඇත."),
        q("පොළොන්නරු යුගයේ 'බිතුසිතුවම් හා මූර්ති' කලා ඉතිහාසයේ හඳුන්වනු ලබන්නේ කුමන ලක්ෂණයක් සහිත යුගයක් ලෙසද?", "බෞද්ධ හා හින්දු කලා ආභාසයන් එක් වූ උසස් සම්භාව්‍ය-අලංකාර යුගය", "කලා නිර්මාණ සම්පූර්ණයෙන් නැවතුණු යුගය", "යුරෝපීය චිත්‍ර අනුකරණය කළ යුගය", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ යුගය", "අනුරාධපුර සම්භාව්‍යත්වයත් දකුණු ඉන්දීය ආභාසයත් මුසු වූ පොහොසත් කලා යුගයක් ලෙස සැලකේ."),
        q("පොළොන්නරුවේ 'සඳකඩපහණේ' ගවයා ඉවත් වීමට අමතරව අලුතින් වැඩි දියුණු වූ ලක්ෂණය කුමක්ද?", "සත්ව පෙළවල් වෙන් වෙන් කවාකාර තීරුවල විස්තරාත්මකව කැටයම් කිරීම", "නෙළුම් මල සම්පූර්ණයෙන් ඉවත් කිරීම", "හංස පෙළ වෙනුවට කපුටු පෙළක් යෙදීම", "සඳකඩපහණ ගඩොලින් තැනීම", "පොළොන්නරු වටදාගේ සඳකඩපහණේ එක් එක් සතාට වෙනම තීරුවක් වෙන් කර කැටයම් අලංකාරය වැඩි කර ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාර හිටි පිළිමයේ' උරහිසේ සිට දණහිස දක්වා සිවුරු රැලි නෙළා ඇති රිද්මය මගින් කුමක් ප්‍රකාශ වේද?", "ශරීරයේ වටකුරු බව හා ස්ථාවර සංයමය", "දැඩි කෝපය හා චංචල බව", "සිවුර සුළඟින් ඉරී ගිය බව", "ශිල්පියාගේ අත් වෙව්ලීම", "පපුව මත දෑත් බැඳගත් ඉරියව්වට අනුකූලව චීවර රැලි ශරීරය වටා මෘදුව ගලා යන සේ නෙළා ඇත."),
        q("පොළොන්නරු යුගයේ 'ලෝකඩ හා පාෂාණ මූර්ති' ආරක්ෂා කිරීමේදී අද වන විට පුරාවිද්‍යා කෞතුකාගාරවල වැදගත්කම කුමක්ද?", "කාලගුණික හානි හා සොරකම්වලින් අමිල කලා කෘති ආරක්ෂා කර අධ්‍යයනයට සැලැස්වීම", "ප්‍රතිමා උණු කර නව කාසි සෑදීම", "ප්‍රතිමා රහසිගතව වළ දැමීම", "සංචාරකයන්ට නැරඹීම තහනම් කිරීම", "පොළොන්නරු හා කොළඹ ජාතික කෞතුකාගාර මෙම උරුමය රැකගෙන සිසුන්ට ප්‍රදර්ශනය කරයි.")
    )
}
